-- CP v151 hooks; gameplay is scoped to Laureate players.
UPDATE CustomModOptions SET Value=1 WHERE Name IN
 ('EVENTS_CITY','EVENTS_PLAYER_TURN','EVENTS_GOLDEN_AGE','EVENTS_UNIT_CREATED',
  'EVENTS_UNIT_UPGRADES','EVENTS_UNIT_CONVERTS','EVENTS_UNIT_CAPTURE','EVENTS_UNIT_PREKILL');
CREATE TEMP TABLE LCClone AS SELECT * FROM "Civilizations" WHERE Type='CIVILIZATION_AMERICA';
UPDATE LCClone SET "ID"=NULL,"Type"='CIVILIZATION_LAUREATE_COMMONWEALTH',"Description"='TXT_KEY_LC_CIV',"ShortDescription"='TXT_KEY_LC_SHORT',"Adjective"='TXT_KEY_LC_ADJECTIVE',"Civilopedia"='TXT_KEY_LC_CIV_PEDIA',"CivilopediaTag"='TXT_KEY_LC_CIV5',"Strategy"='TXT_KEY_LC_STRATEGY',"DefaultPlayerColor"='PLAYERCOLOR_LC',"Playable"=1,"AIPlayable"=0,"PackageID"=NULL,"DawnOfManQuote"='TXT_KEY_LC_DAWN',"DawnOfManAudio"='',"DawnOfManImage"='LC_Dawn.dds',"MapImage"='LC_Map.dds',"PortraitIndex"=0,"IconAtlas"='LC_CIV_ATLAS',"AlphaIconAtlas"='LC_ALPHA_ATLAS';
DROP TABLE LCClone;
CREATE TEMP TABLE LCClone AS SELECT * FROM "Leaders" WHERE Type='LEADER_WASHINGTON';
UPDATE LCClone SET "ID"=NULL,"Type"='LEADER_LAUREA',"Description"='TXT_KEY_LC_LEADER',"Civilopedia"='TXT_KEY_LC_LEADER_PEDIA',"CivilopediaTag"='TXT_KEY_LC_LAUREA',"PackageID"=NULL,"PortraitIndex"=0,"IconAtlas"='LC_LEADER_ATLAS',"ArtDefineTag"='LC_LeaderScene.xml',"DoFWillingness"=6,"DiploBalance"=7,"Loyalty"=8,"Chattiness"=4,"Meanness"=4;
DROP TABLE LCClone;
CREATE TEMP TABLE LCClone AS SELECT * FROM "Units" WHERE Type='UNIT_SWORDSMAN';
UPDATE LCClone SET "ID"=NULL,"Type"='UNIT_LAUREATE_CHAMPION',"Description"='TXT_KEY_LC_UNIT',"Civilopedia"='TXT_KEY_LC_UNIT_PEDIA',"Help"='TXT_KEY_LC_UNIT_HELP',"Strategy"='TXT_KEY_LC_UNIT_STRATEGY',"IconAtlas"='LC_OBJECT_ATLAS',"PortraitIndex"=0,"UnitFlagAtlas"='LC_FLAG_ATLAS',"UnitFlagIconOffset"=0;
DROP TABLE LCClone;
CREATE TEMP TABLE LCClone AS SELECT * FROM "Buildings" WHERE Type='BUILDING_AMPHITHEATER';
UPDATE LCClone SET "ID"=NULL,"Type"='BUILDING_HALL_OF_LAURELS',"Description"='TXT_KEY_LC_HALL',"Civilopedia"='TXT_KEY_LC_HALL_PEDIA',"Help"='TXT_KEY_LC_HALL_HELP',"Strategy"='TXT_KEY_LC_HALL_STRATEGY',"IconAtlas"='LC_OBJECT_ATLAS',"PortraitIndex"=1;
DROP TABLE LCClone;
UPDATE Buildings SET Happiness=Happiness+1 WHERE Type='BUILDING_HALL_OF_LAURELS';
